local TasselMaker = {}
local PRODUCTS = {
    common_thread_tassel = { name = "Navadna resasta kobilica", threadCost = 2, woodCost = 1, time = 2, cost = 25, beauty = 12, happiness = 1, description = "Navadna resasta kobilica iz niti." },
    silk_window_tassel = { name = "Svila okenska kobilica", threadCost = 2, silkCost = 1, woodCost = 1, time = 4, cost = 70, beauty = 25, happiness = 1, prestige = 1, description = "Svila okenska kobilica za zavese." },
    silver_corded_tassel = { name = "Srebrnovrvena kobilica", threadCost = 2, silkCost = 1, silverCost = 1, woodCost = 1, time = 7, cost = 200, beauty = 40, happiness = 2, prestige = 5, description = "Srebrnovrvena kobilica za plemiške dvorane." },
    gold_trimmed_tassel = { name = "Zlatookrasna kobilica", threadCost = 3, silkCost = 2, goldCost = 1, silverCost = 1, time = 11, cost = 520, beauty = 55, happiness = 3, prestige = 13, description = "Zlatookrasna kobilica za visoke plemiče." },
    jewel_top_tassel = { name = "Draguljarska kobilica", threadCost = 3, silkCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, time = 15, cost = 1200, beauty = 70, happiness = 5, prestige = 25, description = "Kobilica z draguljem na vrhu za visoko plemstvo." },
    royal_grand_tassel = { name = "Kraljevski velika kobilica", threadCost = 5, silkCost = 4, goldCost = 2, silverCost = 2, jewelCost = 2, pearlCost = 2, time = 22, cost = 3100, beauty = 90, happiness = 11, prestige = 55, description = "Velika kraljevska kobilica z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    tassel_workshop = { name = "Kobilna delavnica", cost = { gold = 200, wood = 100, stone = 80, thread = 6 }, upkeep = 4, qualityBonus = 5 },
    passementerie_loft = { name = "Pasmenterska delavnica", cost = { gold = 760, wood = 220, stone = 220, silver = 8, silk = 6 }, upkeep = 17, qualityBonus = 18 },
    gold_thread_atelier = { name = "Zlatonitni atelje", cost = { gold = 2200, wood = 340, stone = 480, silver = 28, gold = 6 }, upkeep = 50, qualityBonus = 30 },
    royal_passementerie_palace = { name = "Kraljevska pasmenterska palača", cost = { gold = 9200, wood = 580, stone = 720, gold = 55, jewel = 14 }, upkeep = 185, qualityBonus = 55, prestigeBonus = 50 },
}
TasselMaker.threadStock = 16; TasselMaker.silkStock = 12; TasselMaker.woodStock = 10; TasselMaker.silverStock = 6; TasselMaker.goldStock = 6; TasselMaker.jewelStock = 4; TasselMaker.pearlStock = 4
TasselMaker.productStock = {}; TasselMaker.buildings = {}; TasselMaker.maker = nil; TasselMaker.activeMaking = {}; TasselMaker.totalProducts = 0; TasselMaker.dayTimer = 0
function TasselMaker.init() TasselMaker.threadStock=16; TasselMaker.silkStock=12; TasselMaker.woodStock=10; TasselMaker.silverStock=6; TasselMaker.goldStock=6; TasselMaker.jewelStock=4; TasselMaker.pearlStock=4; TasselMaker.productStock={}; TasselMaker.buildings={}; TasselMaker.maker=nil; TasselMaker.activeMaking={}; TasselMaker.totalProducts=0; TasselMaker.dayTimer=0; print("[TasselMaker] Royal Tassel Maker System initialized (6 products, 4 buildings)") end
function TasselMaker.hireMaker(n,s) s=s or math.random(55,90); local c=440+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TasselMaker.maker={name=n or ("Pasmenter "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pasmenter najet: %s (spretnost: %d)",TasselMaker.maker.name,s),"success") end; return true end
function TasselMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TasselMaker.build(id) local ok,e=TasselMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TasselMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TasselMaker.getQualityBonus() local b=0; for _,bd in ipairs(TasselMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TasselMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.threadCost and TasselMaker.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.silkCost and TasselMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.woodCost and TasselMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.silverCost and TasselMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TasselMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TasselMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TasselMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TasselMaker.buildings==0 then return false,"Potrebna kobilna delavnica" end; if not TasselMaker.maker then return false,"Potreben pasmenter" end; return true end
function TasselMaker.make(pt,qty) qty=qty or 1; local ok,e=TasselMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.threadCost then TasselMaker.threadStock=TasselMaker.threadStock-d.threadCost*qty end; if d.silkCost then TasselMaker.silkStock=TasselMaker.silkStock-d.silkCost*qty end; if d.woodCost then TasselMaker.woodStock=TasselMaker.woodStock-d.woodCost*qty end; if d.silverCost then TasselMaker.silverStock=TasselMaker.silverStock-d.silverCost*qty end; if d.goldCost then TasselMaker.goldStock=TasselMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TasselMaker.jewelStock=TasselMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then TasselMaker.pearlStock=TasselMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if TasselMaker.maker then t=math.max(1,t-math.floor(TasselMaker.maker.skill/14)) end; table.insert(TasselMaker.activeMaking,{id="tassel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vezava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TasselMaker.completeMaking(m) local q=1.0+(TasselMaker.getQualityBonus()/100); if TasselMaker.maker then q=q+(TasselMaker.maker.skill/150) end; q=math.min(2.4,q); TasselMaker.productStock[m.productType]=(TasselMaker.productStock[m.productType] or 0)+m.quantity; TasselMaker.totalProducts=TasselMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TasselMaker.maker then TasselMaker.maker.itemsMade=TasselMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TasselMaker.maker.skill=math.min(100,TasselMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kobilica izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"tassel.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function TasselMaker.update(dt) if not _G.state then return end; TasselMaker.dayTimer=TasselMaker.dayTimer+dt; if TasselMaker.dayTimer>=30 then TasselMaker.dayTimer=0; for i=#TasselMaker.activeMaking,1,-1 do local m=TasselMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TasselMaker.completeMaking(m); table.remove(TasselMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TasselMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TasselMaker.maker then tu=tu+11 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TasselMaker.getStats() return {threadStock=TasselMaker.threadStock,silkStock=TasselMaker.silkStock,woodStock=TasselMaker.woodStock,silverStock=TasselMaker.silverStock,goldStock=TasselMaker.goldStock,jewelStock=TasselMaker.jewelStock,pearlStock=TasselMaker.pearlStock,productStock=TasselMaker.productStock,numBuildings=#TasselMaker.buildings,hasMaker=TasselMaker.maker~=nil,makerName=TasselMaker.maker and TasselMaker.maker.name or "—",makerSkill=TasselMaker.maker and TasselMaker.maker.skill or 0,activeMaking=#TasselMaker.activeMaking,totalProducts=TasselMaker.totalProducts} end
return TasselMaker
